SELECT id, player_id, points, SUM(points) OVER () AS total
FROM games
ORDER BY id;

SELECT id, points, ROUND(AVG(points) OVER (), 1) AS average
FROM games
ORDER BY id;

SELECT id, points, ROUND(points - AVG(points) OVER (), 1) AS diff
FROM games
ORDER BY id;

SELECT id, player_id, points, RANK() OVER (ORDER BY points DESC) AS place
FROM games
ORDER BY place, id;

SELECT id, player_id, points, DENSE_RANK() OVER (ORDER BY points DESC) AS place
FROM games
ORDER BY place, id;

